// Differential checks of AssocStringAppend-pbo.js against Lean, generated by leanscript --check
import * as M from "./AssocStringAppend-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(\"\")", () => M.test1(""), "abcd", false);
check("test1(\"a\")", () => M.test1("a"), "abaaaacd", false);
check("test1(\"hello world\")", () => M.test1("hello world"), "abhello worldhello worldhello worldhello worldcd", false);
check("test1(\"héllo, wörld\")", () => M.test1("héllo, wörld"), "abhéllo, wörldhéllo, wörldhéllo, wörldhéllo, wörldcd", false);
check("test1(\"abcabc\")", () => M.test1("abcabc"), "ababcabcabcabcabcabcabcabccd", false);
check("test1(\"b\")", () => M.test1("b"), "abbbbbcd", false);
check("test1(\"c\")", () => M.test1("c"), "abcccccd", false);
check("test1(\"d\")", () => M.test1("d"), "abddddcd", false);
check("test2(\"\")", () => M.test2(""), "abcd", false);
check("test2(\"a\")", () => M.test2("a"), "abaaaacd", false);
check("test2(\"hello world\")", () => M.test2("hello world"), "abhello worldhello worldhello worldhello worldcd", false);
check("test2(\"héllo, wörld\")", () => M.test2("héllo, wörld"), "abhéllo, wörldhéllo, wörldhéllo, wörldhéllo, wörldcd", false);
check("test2(\"abcabc\")", () => M.test2("abcabc"), "ababcabcabcabcabcabcabcabccd", false);
check("test2(\"b\")", () => M.test2("b"), "abbbbbcd", false);
check("test2(\"c\")", () => M.test2("c"), "abcccccd", false);
check("test2(\"d\")", () => M.test2("d"), "abddddcd", false);
check("test3(\"\")", () => M.test3(""), "abcdefg", false);
check("test3(\"a\")", () => M.test3("a"), "abaaaacdeaaaafg", false);
check("test3(\"hello world\")", () => M.test3("hello world"), "abhello worldhello worldhello worldhello worldcdehello worldhello worldhello worldhello worldfg", false);
check("test3(\"héllo, wörld\")", () => M.test3("héllo, wörld"), "abhéllo, wörldhéllo, wörldhéllo, wörldhéllo, wörldcdehéllo, wörldhéllo, wörldhéllo, wörldhéllo, wörldfg", false);
check("test3(\"abcabc\")", () => M.test3("abcabc"), "ababcabcabcabcabcabcabcabccdeabcabcabcabcabcabcabcabcfg", false);
check("test3(\"b\")", () => M.test3("b"), "abbbbbcdebbbbfg", false);
check("test3(\"c\")", () => M.test3("c"), "abcccccdeccccfg", false);
check("test3(\"d\")", () => M.test3("d"), "abddddcdeddddfg", false);
check("test3(\"e\")", () => M.test3("e"), "abeeeecdeeeeefg", false);
check("test3(\"f\")", () => M.test3("f"), "abffffcdefffffg", false);
check("test3(\"g\")", () => M.test3("g"), "abggggcdeggggfg", false);

console.log(`AssocStringAppend-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
